// MIDI import checks (Phase 4). Samples are generated by samples/make-midi.py.
export async function run({ check, eq, brief, fetchBytes, importBytes }) {
  await check("sample: scale.mid (format 1, tie across barline, chord)", async () => {
    const { score, report } = await importBytes(await fetchBytes("samples/scale.mid"), "scale.mid");
    const [mel, bass] = score.staves;
    if (score.staves.length !== 2) return `${score.staves.length} staves`;
    if (brief(mel) !== "G4:q A4:q B4:q D5:q~ | D5:q r:q F#5:h") return "melody " + brief(mel);
    if (brief(bass) !== "G2+D3:w | C3:h D3:h") return "bass " + brief(bass);
    if (mel.clef !== "treble" || bass.clef !== "bass" || mel.name !== "Melody" || bass.name !== "Bass") return "clefs/names";
    if (!eq(score.measures[0], { key: 1, time: [4, 4] }) || score.tempo !== 120) return JSON.stringify(score.measures[0]) + score.tempo;
    return report.format === "MIDI" || report.format;
  });

  await check("sample: format0.mid (channels; channel 10 becomes a drum staff, DESIGN §27)", async () => {
    const { score } = await importBytes(await fetchBytes("samples/format0.mid"), "format0.mid");
    if (score.staves.length !== 2 || brief(score.staves[0]) !== "C4:q E4:q") return score.staves.map(brief).join(" / ");
    const d = score.staves[1], drums = d.bars[0].filter((e) => e.pitches.length).map((e) => e.pitches.map((p) => p.drum).join("+"));
    return (d.clef === "percussion" && drums.join() === "36,38") || `${d.clef} ${drums}`;
  });

  await check("damaged MIDI gives a message", async () => {
    const b = await fetchBytes("samples/scale.mid");
    try { await importBytes(b.subarray(0, 40), "cut.mid"); return "no error"; }
    catch (e) { return /damaged|incomplete|no notes/.test(e.message) || e.message; }
  });
}
